{
    "QueryLanguage": "JSONPath",
    "Comment": "A description of my state machine",
    "StartAt": "Map",
    "States": {
      "Map": {
        "Type": "Map",
        "InputPath": "$.data",
        "ItemProcessor": {
          "ProcessorConfig": {
            "Mode": "INLINE"
          },
          "StartAt": "Lambda Invoke",
          "States": {
            "Lambda Invoke": {
              "Type": "Task",
              "Resource": "arn:aws:states:::lambda:invoke",
              "OutputPath": "$.Payload",
              "Parameters": {
                "Payload.$": "$",
                "FunctionName": "arn:aws:lambda:us-east-1:533267035849:function:datalake-dev-smb-lambda:$LATEST"
              },
              "Retry": [
                {
                  "ErrorEquals": [
                    "Lambda.ServiceException",
                    "Lambda.AWSLambdaException",
                    "Lambda.SdkClientException",
                    "Lambda.TooManyRequestsException"
                  ],
                  "IntervalSeconds": 60,
                  "MaxAttempts": 5,
                  "BackoffRate": 2,
                  "JitterStrategy": "FULL"
                }
              ],
              "End": true
            }
          }
        },
        "End": true,
        "MaxConcurrency": 10,
        "ResultPath": "$.data.files",
        "ItemsPath": "$.files"
      }
    }
  }
